import{_ as n,o as e,c as t,ag as i}from"./chunks/framework.PVHj0As1.js";const l="/pub-blog/assets/image-20260104230740217.q88nlwml.png",o="/pub-blog/assets/image-20260104230758427.K2_46wl5.png",r="/pub-blog/assets/asynccode.SzD6pBrn.png",s="/pub-blog/assets/image-20260104230821064.DUFb_m1W.png",m=JSON.parse('{"title":"AI 玩转鸿蒙 （一）：选择合适的AI开发工具","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/AI 玩转鸿蒙/AI 玩转鸿蒙 （1）：选择合适的AI开发工具/AI 玩转鸿蒙 （1）：选择合适的AI开发工具.md","filePath":"鸿蒙开发技巧/AI 玩转鸿蒙/AI 玩转鸿蒙 （1）：选择合适的AI开发工具/AI 玩转鸿蒙 （1）：选择合适的AI开发工具.md","lastUpdated":1768196126000,"__rawMarkdown":"# AI 玩转鸿蒙 （一）：选择合适的AI开发工具\\n\\n> **分享人**：万少  \\n> **日期**：2026年1月4日  \\n> **主题**：AI编程工具实践与鸿蒙最新代码生成技巧\\n\\n---\\n\\n# 1. AI编辑器工具\\n\\n## 1.1 AI IDE 工具\\n\\n### Gemini-3-pro\\n- **Trae 海外版**：\\n  - 使用门槛：需要梯子，有费用成本\\n  - 年度会员包含：Claude 4.5等 -> **谷歌 Gemini-3-pro：能用自然语言编写功能**\\n  - 示例：`Gemini-3-pro：帮我使用某个mp4充当开屏动画`\\n- **Trae 国内版**：\\n  - 使用国内主流大模型\\n  - 推理能力：**是否能识别图片**（豆包1.8可以识别截图）\\n\\n### GLM4.6\\n- 示例：`GLM4.6: 使用 xxx/1.mp4 在 Start.ets 中实现开屏动画，播放5s后，跳转到Index.ets`\\n\\n### Codebuddy\\n- **海外版**：考虑后端部署（数据库+后端程序），直连腾讯云相关服务\\n- **国内版**：直连腾讯云相关服务\\n\\n### 阿里 QOder\\n- 编写鸿蒙语言很准确，语法都对\\n- 10月份：one！！！\\n- 价格：**拉满一年 8k**\\n\\n## 1.2 AI 终端工具\\n\\n### IFlow Cli\\n- 内置国内大模型 -> **GLM 4.6 生成70%代码**\\n- 阿里团队出品，心流团队\\n- 号称永久免费！！\\n- 可配置其他大模型，需要api-token\\n\\n### Claude code\\n- 不稳定，需要中转，体验较差\\n- 享受不到AI帮我打工的感觉\\n- 官网言论：我也不喜欢，不想让它赚钱\\n\\n## 1.3 第三方 AI API\\n\\n\\n\\n## 1.4 万少AI编辑器总结\\n- **Trae 海外版**：Gemini-3-pro，会员年费600多人民币\\n- **国内版**：GLM4.7 \\n\\n# 2. APP图片处理\\n\\n## 2.1 图片生成问题\\n- **豆包生成图片**：有AI标识\\n- **解决方案**：使用百度图片工具移除豆包图片的AI标识\\n\\n## 2.2 图片示例\\n![image-20260104230740217](assets/image-20260104230740217.png)\\n\\n# 3. 如何保证生成的鸿蒙代码是最新的\\n\\n> **问题**：旧的鸿蒙代码都不是API11及以上版本，api9、java版本代码错乱\\n\\n## 3.1 配置MCP工具 - Context7\\n\\n> 各大AI编辑器的官网都会有对应的配置方法\\n\\n**Context7能力**：自动搜索其库中最新的鸿蒙文档和语法\\n\\n- 万少已将鸿蒙开发文档（1w多个文档）全部上传到Context7\\n- 支持API20等最新版本\\n\\n使用方法\\n\\n> 帮我生成xx代码  use Context\\n\\n## 3.2 文档喂给AI的方法\\n\\n### 3.2.1 直接喂网址\\n- 使用谷歌Gemini-3是可行的\\n\\n### 3.2.2 保存网址为MD文档后喂给AI\\n\\n![image-20260104230758427](assets/image-20260104230758427.png)\\n\\n![保存网址为MD](assets/asynccode.png)\\n\\n### 3.2.3 推荐使用万少IMA知识库\\n![image-20260104230821064](assets/image-20260104230821064.png)\\n\\n# 4. 下期预告\\n\\n## 4.1 主题：如何在鸿蒙中直接生成图片素材及使用\\n\\n### 4.1.1 直接生成SVG图片图标\\n### 4.1.2 页面素材配置脚本\\n\\n---\\n\\n# 5. 总结与实用建议\\n\\n## 5.1 工具选择建议\\n\\n### 对于国内开发者：\\n1. **IFlow Cli**：免费，内置GLM4.6，适合日常开发\\n2. **Trae国内版**：使用国内大模型，无需梯子\\n3. **豆包1.8**：图片识别能力强\\n\\n### 对于海外或有梯子的开发者：\\n1. **Gemini-3-pro**：自然语言编程能力强\\n2. **Trae海外版**：功能全面，但需要会员\\n\\n## 5.2 鸿蒙开发最佳实践\\n\\n1. **一定要使用Context7**：确保生成的代码是最新API版本\\n2. **文档预处理**：将官方文档保存为MD格式再喂给AI\\n3. **版本验证**：生成代码后检查API版本号\\n\\n## 5.3 成本考虑\\n\\n| 工具 | 费用 | 适合人群 |\\n|------|------|----------|\\n| IFlow Cli | 免费 | 所有开发者 |\\n| Trae海外版 | 600+/年 | 专业开发者 |\\n| 阿里QOder | 8000/年 | 企业级鸿蒙开发 |\\n\\n---\\n\\n**分享要点回顾**：\\n1. AI编程工具能显著提升开发效率\\n2. 鸿蒙开发要注意API版本兼容性\\n3. 正确的工具配置是关键\\n4. 下期将深入图片素材生成\\n\\n**Q&A环节准备问题**：\\n\\n1. 如何选择适合自己的AI编程工具？\\n2. Context7的具体配置步骤？\\n3. 鸿蒙API版本升级的注意事项？ "}'),d={name:"鸿蒙开发技巧/AI 玩转鸿蒙/AI 玩转鸿蒙 （1）：选择合适的AI开发工具/AI 玩转鸿蒙 （1）：选择合适的AI开发工具.md"};function h(u,a,c,_,I,g){return e(),t("div",null,[...a[0]||(a[0]=[i("",62)])])}const A=n(d,[["render",h]]);export{m as __pageData,A as default};
